package io.github.devmrko.companion.adapter;
import java.nio.file.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import tools.jackson.databind.json.JsonMapper;
import io.github.devmrko.companion.domain.Models.Connection;
import static org.junit.jupiter.api.Assertions.*;
/** Fixtures generated by Launchpad deploy/render_companion_connections.py; synthetic IDs only. */
class CompanionBundleContractTest {
 @TempDir Path temp;
 @Test void consumesGeneratedMultiAppBundle()throws Exception {
  for(String name:new String[]{"agent-connections.json","agent-credentials.json","oke-workloads.json"})try(var in=getClass().getResourceAsStream("/generated-connections/"+name)){assertNotNull(in);Files.copy(in,temp.resolve(name));}
  var registry=new AgentConnectionRegistry(temp.resolve("agent-connections.json").toString(),temp.resolve("agent-credentials.json").toString());
  var c=new Connection("DEFAULT","ocid1.tenancy.oc1..synthetic","ocid1.user.oc1..synthetic","ap-seoul-1","synthetic",false);String comp="ocid1.compartment.oc1..synthetic";
  var apps=registry.list(c,"ap-seoul-1",comp);assertEquals(2,apps.size());var credentials=registry.credentials(c,"ap-seoul-1",comp);assertEquals(2,credentials.size());
  for(var app:apps){assertTrue(credentials.stream().anyMatch(x->x.id().equals(app.credentialRef())));assertEquals(app,registry.get(c,"ap-seoul-1",comp,app.id()));}
  var targets=JsonMapper.builder().build().readValue(Files.readString(temp.resolve("oke-workloads.json")),OkeWorkloadHealth.Target[].class);assertEquals(1,targets.length);var t=targets[0];var oke=registry.get(c,t.region(),t.compartment(),t.appId());assertTrue(oke.dependencies().stream().anyMatch(d->d.type().equals("OKE")&&d.ocid().equals(t.clusterId())));assertFalse(t.inspectNodes());
  assertTrue(registry.list(c,"ap-seoul-1","ocid1.compartment.oc1..other").isEmpty());
 }
}
